    local inverseFactorTimesTwo = inverseFactor * inverseFactor
    local factorTimes2 = t * t
    local factor1 = inverseFactorTimesTwo * inverseFactor
    local factor2 = 3 * t * inverseFactorTimesTwo
    local factor3 = 3 * factorTimes2 * inverseFactor
