--- Transforms the vec3 with a mat3.
-- 
-- @param a the vector to transform
-- @param m the 3x3 matrix to transform with
-- @returns out
function ____exports.transformMat3(self, a, m)
    local out = {0, 0, 0}
    local x = a[1]
    local y = a[2]
    local z = a[3]
    out[1] = x * m[1] + y * m[4] + z * m[7]
    out[2] = x * m[2] + y * m[5] + z * m[8]
    out[3] = x * m[3] + y * m[6] + z * m[9]
    return out
end
--- Transforms the vec3 with a quat
-- Can also be used for dual quaternions. (Multiply it with the real part)
-- 
-- @param a the vector to transform
-- @param q quaternion to transform with
-- @returns out
function ____exports.transformQuat(self, a, q)
    local out = {0, 0, 0}
    local qx = q[1]
    local qy = q[2]
    local qz = q[3]
    local qw = q[4]
    local x = a[1]
    local y = a[2]
    local z = a[3]
    local uvx = qy * z - qz * y
    local uvy = qz * x - qx * z
    local uvz = qx * y - qy * x
    local uuvx = qy * uvz - qz * uvy
    local uuvy = qz * uvx - qx * uvz
    local uuvz = qx * uvy - qy * uvx
    local w2 = qw * 2
    uvx = uvx * w2
    uvy = uvy * w2
    uvz = uvz * w2
    uuvx = uuvx * 2
    uuvy = uuvy * 2
    uuvz = uuvz * 2
    out[1] = x + uvx + uuvx
    out[2] = y + uvy + uuvy
    out[3] = z + uvz + uuvz
    return out
