--- Rotate a 3D vector around the x-axis
-- 
-- @param a The vec3 point to rotate
-- @param b The origin of the rotation
-- @param rad The angle of rotation in radians
-- @returns out
function ____exports.rotateX(self, a, b, rad)
    local out = {0, 0, 0}
    local p = {}
    local r = {}
    p[1] = a[1] - b[1]
    p[2] = a[2] - b[2]
    p[3] = a[3] - b[3]
    r[1] = p[1]
    r[2] = p[2] * math.cos(rad) - p[3] * math.sin(rad)
    r[3] = p[2] * math.sin(rad) + p[3] * math.cos(rad)
    out[1] = r[1] + b[1]
    out[2] = r[2] + b[2]
    out[3] = r[3] + b[3]
